/* Care is the action layer. Existing medications remain the source of dose settings. */
const careDate=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const careShift=(date,n)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+Number(n));return careDate(d)};
const careToday=()=>careDate();
const careId=()=>crypto.randomUUID();
let careTab='今日';let careOpeningMedHistory=false;
function careStore(){const p=currentPet();p.care||={tasks:[],history:[],sources:[]};if(!p.care.migrated){if(state.review)p.care.tasks.push({id:careId(),type:'复诊',name:'复诊',date:state.review,time:state.reviewTime||'10:00',repeat:false,days:1,remind:true,notes:p.reviewNote||'',legacyReview:true});p.care.migrated=true;}state.meds.forEach(m=>{if(!m.startDate)m.startDate=careShift(careToday(),-Math.min(+m.day||0,Math.max(0,+m.days-1)));if(!m.dailyLogs){m.dailyLogs={};m.dailyLogs[careToday()]={...(m.logs||{})};m.logDate=careToday();}for(const [date,logs] of Object.entries(m.dailyLogs)){for(const [time,done] of Object.entries(logs)){const key=`med:${m.id}:${date}:${time}`;if(done&&!p.care.history.some(h=>h.key===key))p.care.history.push({key,id:String(m.id),type:'用药',name:m.name,detail:`${m.dose} · ${m.method}`,date,time,completedAt:date+'T'+time+':00'});}}});syncCareReview(p.care);return p.care;}
const oldDoseLog=logFor;
logFor=function(m){if(!m.dailyLogs){const logs=oldDoseLog(m);m.dailyLogs={[careToday()]:{...logs}};}m.logDate=careToday();m.logs=m.dailyLogs[careToday()]||={};return m.logs;};
function medEnd(m){return careShift(m.startDate||careToday(),Math.max(0,+m.days-1));}
function medActive(m){return !m.ended&&m.startDate<=careToday()&&medEnd(m)>=careToday();}
function taskEnd(t){return t.repeat?careShift(t.date,+t.days-1):t.date;}
function careOccurrences(){const c=careStore(),today=careToday(),items=[];state.meds.filter(medActive).forEach(m=>timesFor(m).forEach(time=>items.push({key:`med:${m.id}:${today}:${time}`,med:m,id:String(m.id),type:'用药',name:m.name,detail:`${m.dose} · ${m.method}`,date:today,time,done:!!logFor(m)[time],remind:!!m.reminders?.[time]})));c.tasks.forEach(t=>{if(t.date>today||t.repeat&&taskEnd(t)<today)return;const date=t.repeat?today:t.date;const key=`task:${t.id}:${date}`,completed=c.history.find(h=>h.key===key);if(completed&&(completed.completedDate||completed.date)<today)return;items.push({key,id:t.id,type:t.type,name:t.name,detail:t.notes|| (t.repeat?'每日照护':t.type==='复诊'?'按预约到院':'按计划完成'),date,time:t.time,done:c.history.some(h=>h.key===key),remind:t.remind});});return items.sort((a,b)=>Number(a.done)-Number(b.done)||a.date.localeCompare(b.date)||a.time.localeCompare(b.time));}
function careRecordDose(m,time,done){const today=careToday(),key=`med:${m.id}:${today}:${time}`,c=careStore();logFor(m)[time]=done;m.taken=timesFor(m).every(t=>logFor(m)[t]);c.history=c.history.filter(h=>h.key!==key);if(done)c.history.unshift({key,id:String(m.id),type:'用药',name:m.name,detail:`${m.dose} · ${m.method}`,date:today,time,completedDate:careToday(),completedAt:new Date().toISOString()});savePets();}
function careComplete(item,done){if(item.med){careRecordDose(item.med,item.time,done);return;}const c=careStore();c.history=c.history.filter(h=>h.key!==item.key);state.extraRecords=state.extraRecords.filter(r=>r.careKey!==item.key);if(done){c.history.unshift({...item,completedDate:careToday(),completedAt:new Date().toISOString()});if(['复诊','疫苗','驱虫'].includes(item.type))state.extraRecords.unshift({recordId:'care-'+careId(),careKey:item.key,date:careToday().replaceAll('-','.'),type:item.type==='复诊'?'就诊':item.type,name:item.name,hospital:'照护完成记录',doctor:'主人确认',tags:[item.type,'已完成'],result:'已确认完成；可另行补充医院报告。'});}savePets();}
function careEmpty(title,detail=''){return `<div class="care-empty">${I('heart')}<b>${title}</b>${detail?`<p>${detail}</p>`:''}</div>`;}
const careIcon=t=>({用药:'pill',护理:'heart',复诊:'calendar',疫苗:'shield',驱虫:'shield'})[t]||'heart';
function careItemHTML(item){return `<article class="care-task-row ${item.done?'is-done':''}"><span class="care-task-symbol">${I(careIcon(item.type))}</span><div class="care-task-copy"><div class="care-task-meta">${esc(item.type)} · ${esc(item.done?'已完成 · '+item.time:item.date<careToday()?'待补办 '+item.date:item.time)}${item.remind?' · 提醒已开':''}</div><b>${esc(item.name)}</b><p>${esc(item.detail)}</p></div><button class="care-check ${item.done?'checked':''}" data-care-complete="${esc(item.key)}" aria-label="${item.done?'撤销':'完成'}${esc(item.name)}" aria-pressed="${item.done}">${I(item.done?'check':'plus')}</button></article>`;}
function careHeader(title){header.innerHTML=`<div class="page-head"><button data-action="back" aria-label="返回">${I('back')}</button><h1>${title}</h1><span></span></div>`;}
function renderCareHub(){careHeader('照护');const c=careStore(),items=careOccurrences(),pending=items.filter(t=>!t.done),done=items.filter(t=>t.done);scroll.innerHTML=`<div class="care-pet-line">${avatar()}<div><b>${esc(currentPet().name)}的照护</b><small>${careToday().replaceAll('-','.')} · ${pending.length?'还有 '+pending.length+' 项待完成':items.length?'今日任务已完成':'今天暂无待办'}</small></div></div><div class="care-segments" role="tablist" aria-label="照护分类">${['今日','计划','已完成'].map(t=>`<button role="tab" aria-selected="${careTab===t}" class="${careTab===t?'selected':''}" data-care-tab="${t}">${t}</button>`).join('')}</div>${careTab==='今日'?`<section class="care-daily-summary"><div><strong>${done.length}<small> / ${items.length}</small></strong><span>今日已完成</span></div><div class="care-progress"><i style="width:${items.length?done.length/items.length*100:0}%"></i></div></section><div class="care-task-list">${items.length?items.map(careItemHTML).join(''):careEmpty('今天暂无照护任务','可从就诊记录生成计划')}</div><button class="care-text-route" data-care-tab="计划">查看全部计划 ${I('arrow')}</button>`:careTab==='计划'?`<div class="care-section-heading"><h2>照护计划</h2><button data-care-add>＋ 添加</button></div><button class="care-med-entry" data-route="medication">${I('pill')}<div><b>用药管理</b><small>${state.meds.filter(m=>!m.ended&&medEnd(m)>=careToday()).length} 项用药计划 · 剂量、频次与提醒</small></div>${I('chevron')}</button>${c.tasks.filter(t=>t.repeat||!c.history.some(h=>h.id===t.id)).map(t=>`<button class="care-plan-row" data-care-edit="${t.id}"><span class="care-task-symbol">${I(careIcon(t.type))}</span><div><span class="care-task-meta">${esc(t.type)}</span><b>${esc(t.name)}</b><small>${esc(t.date)}${t.repeat?'起 · 每日 · '+t.days+' 天'+(taskEnd(t)<careToday()?' · 已结束':''):''} · ${esc(t.time)}</small></div>${I('chevron')}</button>`).join('')}${!c.tasks.length&&!state.meds.length?careEmpty('还没有照护计划','添加任务，或从就诊记录生成'):''}`:`<div class="care-section-heading"><h2>完成记录</h2><span>${c.history.length} 项</span></div>${c.history.length?c.history.slice(0,60).map(h=>`<div class="care-history-row">${I('check')}<div><b>${esc(h.name)}</b><p>${esc(h.type)} · ${esc(h.completedDate||h.date)} ${esc(h.time)}</p></div>${careOccurrences().some(t=>t.key===h.key)?`<button data-care-undo="${esc(h.key)}">撤销</button>`:''}</div>`).join(''):careEmpty('暂无完成记录','完成任务后会自动保留')}<button class="care-text-route" data-route="archive">查看长期医疗档案 ${I('arrow')}</button>`}`;}
function renderCareMedication(){careStore();careHeader(state.medTab==='用药历史'?'历史用药':'用药管理');const history=state.medTab==='用药历史',list=state.meds.filter(m=>history?m.ended||medEnd(m)<careToday():!m.ended&&medEnd(m)>=careToday());scroll.innerHTML=`<div class="care-breadcrumb">${history?'档案 / 历史用药':'照护 / 用药管理'}</div>${petMini()}${history?'':`<button class="care-text-route" data-care-med-history>查看历史用药 ${I('chevron')}</button>`}${list.map(m=>{const logged=Object.values(m.dailyLogs||{}).filter(v=>Object.values(v).some(Boolean)).length;return `<article class="care-med-card"><div class="care-med-heading"><span class="care-task-symbol">${I('pill')}</span><div><h2>${esc(m.name)}</h2><p>${esc(m.method)}</p></div>${history?'<span class="care-badge">疗程已结束</span>':''}</div><div class="care-med-stats"><div><small>单次剂量</small><b>${esc(m.dose)}</b></div><div><small>每日次数</small><b>${esc(m.frequency)}</b></div><div><small>疗程</small><b>${m.days} 天</b></div></div><p class="care-med-dates">${esc(m.startDate)} — ${medEnd(m)} · 已记录 ${logged} 天</p>${history?`<p class="care-med-dates">${Object.values(m.dailyLogs||{}).reduce((n,logs)=>n+Object.values(logs).filter(Boolean).length,0)} 次服药记录</p>${careDoseHistory(m)}`:`${medActive(m)?doseRows(m):'<p class="care-med-dates">计划尚未开始</p>'}<div class="care-med-actions"><button data-med-settings="${m.id}">${I('clock')}时间与提醒</button><button data-care-med-edit="${m.id}">${I('edit')}处方信息</button><button data-care-med-end="${m.id}">结束疗程</button></div><button class="supplement-row" data-short-edit="med" data-id="${m.id}"><span>用药备注</span><small>${esc(m.notes||'添加备注')}</small>${I('chevron')}</button>`}</article>`;}).join('')}${!list.length?careEmpty(history?'暂无历史用药':'暂无当前用药',history?'结束的疗程会保留在这里':'按医生已有处方添加'):''}${history?'':`<button class="add-button" data-action="add-med">${I('plus')}添加用药</button>`}<p class="microcopy centered">按医生处方设置；提醒仅在演示内展示</p>`;}
function editCareTask(id,defaultType="护理"){const c=careStore(),t=c.tasks.find(t=>t.id===id)||{id:careId(),type:defaultType,name:defaultType==='复诊'?'复诊':'',date:careToday(),time:'09:00',repeat:false,days:7,remind:true,notes:''};openLightEditor(id?'修改照护任务':'添加照护任务',`<form id="care-task-form" class="entry-form"><label>任务类型<select name="type">${['护理','复诊','疫苗','驱虫'].map(v=>`<option ${t.type===v?'selected':''}>${v}</option>`).join('')}</select></label><label>任务名称<input name="name" maxlength="40" value="${esc(t.name)}" required placeholder="按医嘱填写"></label><div class="form-row"><label>日期<input name="date" type="date" value="${t.date}" required></label><label>时间<input name="time" type="time" value="${t.time}" required></label></div><label>执行方式<select name="repeat"><option value="once" ${!t.repeat?'selected':''}>仅一次</option><option value="daily" ${t.repeat?'selected':''}>每日一次</option></select></label><label data-task-days ${!t.repeat?'hidden':''}>持续天数<input name="days" type="number" min="1" max="365" value="${t.days||7}"></label><label>备注<textarea name="notes" maxlength="300">${esc(t.notes)}</textarea></label><label class="plan-reminder"><input type="checkbox" name="remind" ${t.remind?'checked':''}>开启提醒</label></form>${id?`<button class="delete-entry" data-care-delete="${t.id}">删除计划</button>`:''}`,d=>{const values=Object.fromEntries(d);if(!values.name.trim())return;Object.assign(t,values,{name:values.name.trim(),repeat:values.repeat==='daily',days:values.repeat==='daily'?+values.days:1,remind:d.has('remind')});if(!id)c.tasks.push(t);if(t.legacyReview){state.review=t.date;state.reviewTime=t.time;currentPet().reviewNote=t.notes;}savePets();closeLightEditor();render();toast('照护计划已保存');});lightEditor.node.querySelector('[name=repeat]').onchange=e=>lightEditor.node.querySelector('[data-task-days]').hidden=e.target.value!=='daily';}
function careHealthArchive(){modal('长期健康资料',`${petMini()}<div class="care-health-record"><h3>过敏史</h3><p>${esc(currentPet().allergies||'未填写')}</p><h3>既往病史</h3><p>${esc(currentPet().medicalHistory||'未填写')}</p><h3>照护备注</h3><p>${esc(currentPet().notes||'未填写')}</p></div><button class="cta" data-pet-action="edit">编辑宠物资料</button>`);}
function careArchiveHistory(){modal('照护完成记录',careStore().history.length?careStore().history.map(h=>`<div class="care-history-row">${I(careIcon(h.type))}<div><b>${esc(h.name)}</b><p>${esc(h.completedDate||h.date)} ${esc(h.time)} · ${esc(h.type)}</p><p>${esc(h.detail||'')}</p></div></div>`).join(''):careEmpty('暂无照护历史'));}
function carePlanDraft(){const r=visitHospitalRecord(),d=r?.voiceDetails||{drugName:'处方口服药 A（演示）',dose:'按医生处方',frequency:'2',days:'7',treatment:medicalEditValue(2),advice:medicalEditValue(3)};const text=(d.treatment||'')+' '+(d.advice||'');const daily=/(?:每日|每天)(?:一次)?(?:进行)?(?:肠胃|皮肤|伤口)?护理|护理[，：: ]*(?:每日|每天)/.test(text),nursing=/护理/.test(text),review=text.match(/(\d+|七|一|二|三|四|五|六|八|九|十)\s*天后.*复诊/);const number=v=>({一:1,二:2,三:3,四:4,五:5,六:6,七:7,八:8,九:9,十:10})[v]||+v;return {source:r?.recordId||'default-visit',record:r,d,nursing,daily,reviewDays:review?number(review[1]):null,hasReview:/复诊/.test(text)};}
function openCarePlan(){const draft=carePlanDraft(),c=careStore();if(c.sources.includes(draft.source)){modal('本次照护计划',`<div class="detail"><b>本次就诊已生成计划</b><p>在照护中调整时间和提醒，避免重复添加。</p></div><button class="cta" data-route="carehub">查看照护计划</button>`);return;}const {d}=draft;const existingMed=state.meds.some(m=>m.sourceVisit===draft.source);modal('确认照护计划',`<form id="care-plan-form" class="entry-form"><p class="care-plan-source">${esc(currentPet().name)} · ${esc(draft.record?.hospital||selectedVisitHospital())}</p><p class="microcopy">根据已确认医嘱整理，请核对执行日期与频次。</p><label>开始执行日期<input name="start" type="date" value="${careToday()}" required></label>${d.drugName?`<fieldset class="care-draft-group"><legend><label><input type="checkbox" name="includeMed" ${existingMed?'disabled':'checked'}>用药</label></legend><b>${esc(d.drugName)}</b>${existingMed?'<p class="microcopy">已有用药计划，保留当前设置</p>':''}<p>单次 ${esc(d.dose)} · 每日 ${esc(d.frequency)} 次 · ${esc(d.days)} 天</p>${Array.from({length:Math.min(4,+d.frequency||2)},(_,i)=>`<label>第 ${i+1} 次时间<input name="dose${i}" type="time" required value="${({1:['20:00'],2:['08:00','20:00'],3:['08:00','14:00','20:00'],4:['08:00','12:00','16:00','20:00']})[Math.min(4,+d.frequency||2)][i]}"></label>`).join('')}</fieldset>`:''}${draft.nursing?`<fieldset class="care-draft-group"><legend><label><input type="checkbox" name="includeNursing" ${draft.daily?'checked':''}>护理</label></legend><label>护理事项<input name="nursingName" value="按医嘱护理" maxlength="60"></label><p class="care-source-quote">${esc(d.treatment)}</p><div class="form-row"><label>执行方式<select name="nursingRepeat"><option value="daily">每日一次</option><option value="once">仅一次</option></select></label><label>持续天数<input type="number" name="nursingDays" min="1" max="365" value="" placeholder="按医嘱确认"></label></div><label>护理时间<input type="time" name="nursingTime" value="09:00"></label>${!draft.daily?'<p class="microcopy">医嘱未注明频次，确认后再勾选。</p>':''}</fieldset>`:''}${draft.hasReview?`<fieldset class="care-draft-group"><legend><label><input type="checkbox" name="includeReview" ${draft.reviewDays?'checked':''}>复诊</label></legend><p class="care-source-quote">${esc(d.advice)}</p><label>复诊日期<input name="reviewDate" type="date" value="${draft.reviewDays?careShift(draft.record?.date.replaceAll('.','-')||careToday(),draft.reviewDays):''}"></label><label>提醒时间<input name="reviewTime" type="time" value="10:00"></label>${!draft.reviewDays?'<p class="microcopy">暂无明确日期，请确认后勾选。</p>':''}</fieldset>`:''}<label class="plan-reminder"><input name="remind" type="checkbox" checked>开启所选任务提醒</label><p class="care-plan-error" role="alert"></p><button type="submit" class="cta">确认加入照护</button><button type="button" class="care-text-route" data-route="visit">稍后设置</button></form>`);const form=sheet.querySelector('#care-plan-form');form._draft=draft;for(const group of form.querySelectorAll('.care-draft-group')){const check=group.querySelector('input[type=checkbox]');const update=()=>group.querySelectorAll('input:not([type=checkbox]),select').forEach(el=>el.disabled=!check.checked);check.onchange=update;update();}form.classList.add('grouped-edit-form');form.dataset.baseline=serializeEdit(form);}
planSetup=openCarePlan;
function confirmCarePlan(form){const d=Object.fromEntries(new FormData(form)),draft=form._draft||carePlanDraft(),c=careStore(),error=form.querySelector('.care-plan-error');if(c.sources.includes(draft.source)){error.textContent='本次就诊已生成计划。';return;}if(!d.includeMed&&!d.includeNursing&&!d.includeReview){error.textContent='请选择至少一项任务。';return;}if(d.includeNursing&&(!d.nursingName?.trim()||!d.nursingTime||(d.nursingRepeat==='daily'&&(!d.nursingDays||+d.nursingDays<1)))){error.textContent='请补充护理事项、时间与持续天数。';return;}if(d.includeReview&&(!d.reviewDate||!d.reviewTime)){error.textContent='请确认复诊日期和提醒时间。';return;}const times=Array.from({length:Math.min(4,+draft.d.frequency||2)},(_,i)=>d['dose'+i]);if(d.includeMed&&(times.some(t=>!t)||new Set(times).size!==times.length)){error.textContent='请为每次用药设置不同时间。';return;}
 if(d.includeMed&&!state.meds.some(m=>m.sourceVisit===draft.source))state.meds.push({id:Date.now(),sourceVisit:draft.source,name:draft.d.drugName,method:'口服 · 按处方',dose:draft.d.dose,frequency:'每日 '+times.length+' 次',days:+draft.d.days,day:0,startDate:d.start,schedule:times.sort(),logs:{},dailyLogs:{},reminders:Object.fromEntries(times.map(t=>[t,!!d.remind]))});
 if(d.includeNursing)c.tasks.push({id:careId(),sourceVisit:draft.source,type:'护理',name:d.nursingName.trim(),date:d.start,time:d.nursingTime,repeat:d.nursingRepeat==='daily',days:d.nursingRepeat==='daily'?+d.nursingDays:1,remind:!!d.remind,notes:draft.d.treatment});
 if(d.includeReview)c.tasks.push({id:careId(),sourceVisit:draft.source,type:'复诊',name:'复诊',date:d.reviewDate,time:d.reviewTime,repeat:false,days:1,remind:!!d.remind,notes:draft.record?.hospital||selectedVisitHospital()});
 c.sources.push(draft.source);savePets();sheet.close();careTab='今日';go('carehub');toast('照护计划已生成');}
function careGoMedication(history=false){careOpeningMedHistory=history;state.medTab=history?'用药历史':'当前用药';go('medication');careOpeningMedHistory=false;}
function editCareMedicine(id){const m=state.meds.find(m=>m.id===+id);if(!m)return;modal('编辑处方信息',`<form id="care-med-form" class="entry-form" data-id="${m.id}">${editGroup('处方信息',editRow('药名','name',m.name,'text','required maxlength="40"')+editRow('单次剂量','dose',m.dose,'text','required maxlength="30"')+editRow('使用方式','method',m.method,'text','required maxlength="30"'))}${editGroup('疗程',editRow('开始日期','startDate',m.startDate,'date','required')+editRow('疗程（天）','days',m.days,'number','required min="1" max="365"'))}<p class="microcopy">仅根据医生已有处方修改。</p><button type="submit" class="cta">保存</button></form>`);const f=sheet.querySelector('form');f.classList.add('grouped-edit-form');f.dataset.baseline=serializeEdit(f);sheet.classList.add('core-editor');sheet.querySelector('.sheet-head').insertAdjacentHTML('beforeend',`<button class="core-save" type="submit" form="care-med-form">保存</button>`);}
const careNavItems=[['home','home','首页'],['care','stethoscope','就医'],['medicine','heart','照护'],['archive','file','档案'],['pet','user','我的']];
nav.innerHTML=careNavItems.map(([key,ic,name])=>`<button data-nav="${key}">${I(ic)}${name}</button>`).join('');
const syncBeforeCare=syncCoreNavigation;
