const careDayLabel=date=>{const d=new Date(date+'T12:00:00');return ['日','一','二','三','四','五','六'][d.getDay()]};
function careUpcomingPlans(c){const today=careToday(),plans=[];c.tasks.forEach(t=>{if(t.repeat){for(let n=0;n<Math.min(+t.days||1,21);n++){const date=careShift(t.date,n);if(date>today&&date<=taskEnd(t))plans.push({...t,date});}}else if(t.date>today&&!c.history.some(h=>h.id===t.id))plans.push({...t});});state.meds.filter(m=>!m.ended&&medEnd(m)>today).forEach(m=>{for(let n=1;n<=Math.min(14,Math.max(0,Math.round((new Date(medEnd(m))-new Date(today))/86400000)));n++){const date=careShift(today,n);if(date>=m.startDate&&date<=medEnd(m))timesFor(m).forEach(time=>plans.push({id:String(m.id),med:m,type:'用药',name:m.name,detail:`${m.dose} · ${m.method}`,date,time}));}});return plans.sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time));}
function carePlanCompact(item){return `<button class="care-plan-compact" ${item.med?`data-med-settings="${esc(item.med.id)}"`:`data-care-edit="${esc(item.id)}"`}><span class="care-task-symbol">${I(careIcon(item.type))}</span><time>${esc(item.time)}</time><div><b>${esc(item.name)}</b><small>${esc(item.detail||item.notes||item.type)}</small></div>${I('chevron')}</button>`;}
function carePlanFeature(item){return `<button class="care-plan-feature" data-care-edit="${esc(item.id)}"><div class="care-plan-feature-top"><span class="care-task-symbol">${I(careIcon(item.type))}</span><span>${esc(item.type)} · 重要节点</span><time>${esc(item.date.slice(5).replace('-','/'))}</time></div><b>${esc(item.name)}</b><p>${esc(item.notes||'请提前确认时间与所需资料')}</p><div>查看计划 ${I('chevron')}</div></button>`;}
function carePlanGroup(title,list){if(!list.length)return '';const important=list.filter(x=>['复诊','疫苗'].includes(x.type)),ordinary=list.filter(x=>!important.includes(x));return `<section class="care-plan-group"><div class="care-plan-group-title"><h2>${title}</h2><span>${list.length} 项</span></div>${important.map(carePlanFeature).join('')}${ordinary.length?`<div class="care-plan-list">${ordinary.map(carePlanCompact).join('')}</div>`:''}</section>`;}
function renderCareToday(items,done,pending){const next=pending[0];return `<section class="care-summary-card"><div class="care-summary-copy"><span>今日完成</span><strong>${done.length}<small> / ${items.length}</small></strong></div><div class="care-summary-main"><div class="care-progress" role="progressbar" aria-valuenow="${done.length}" aria-valuemax="${items.length||1}"><i style="width:${items.length?done.length/items.length*100:0}%"></i></div><p>${next?`下一任务 <b>${esc(next.time)} ${esc(next.name)}</b>`:'今天的任务已处理完成'}</p></div></section>${next?`<section class="care-next-section"><div class="care-block-title"><h2>接下来要做</h2><span class="care-status">${next.date<careToday()?'待补办':'待完成'}</span></div><article class="care-next-card"><div class="care-next-time"><b>${esc(next.time)}</b><span>${esc(next.type)}</span></div><span class="care-task-symbol">${I(careIcon(next.type))}</span><button class="care-task-copy care-task-detail" data-care-task-detail="${esc(next.key)}"><b>${esc(next.name)}</b><p>${esc(next.detail)}</p></button><button class="care-check" data-care-complete="${esc(next.key)}" aria-label="完成${esc(next.name)}">${I('check')}</button></article></section>`:''}<section class="care-all-section"><div class="care-block-title"><h2>今日全部任务</h2><span>${items.length} 项</span></div><div class="care-task-list care-open-tasks">${pending.length?pending.map(careItemHTML).join(''):careEmpty('今天没有待办任务','可以查看之后的计划')}</div>${done.length?`<details class="care-completed-fold"><summary>${I('check')}<span>今日已完成 ${done.length} 项</span>${I('chevron')}</summary><div>${done.map(careItemHTML).join('')}</div></details>`:''}</section>`;}
function renderCarePlan(c){const today=careToday(),week=Array.from({length:7},(_,i)=>careShift(today,i)),plans=careUpcomingPlans(c),selected=plans.filter(x=>x.date===carePlanSelectedDate),tomorrow=plans.filter(x=>x.date===careShift(today,1)),weekEnd=careShift(today,7),thisWeek=plans.filter(x=>x.date>careShift(today,1)&&x.date<=weekEnd),later=plans.filter(x=>x.date>weekEnd),reviews=plans.filter(x=>x.type==='复诊').length;return `<div class="care-plan-toolbar"><div class="care-week-strip">${week.map((date,i)=>`<button class="${carePlanSelectedDate===date?'selected':''}" data-care-date="${date}"><span>${i===0?'今天':'周'+careDayLabel(date)}</span><b>${+date.slice(-2)}</b><i></i></button>`).join('')}</div><section class="care-plan-summary"><div><span>近期计划</span><b>本周 ${plans.filter(x=>x.date<=weekEnd).length} 项任务</b></div><em>${reviews} 次复诊</em><button data-care-add>＋ 添加计划</button></section></div>${selected.length?`<section class="care-selected-day"><div class="care-plan-group-title"><h2>${carePlanSelectedDate===today?'今天':carePlanSelectedDate.slice(5).replace('-','月')+'日'}的安排</h2><span>${selected.length} 项</span></div><div class="care-plan-list">${selected.map(carePlanCompact).join('')}</div></section>`:''}${carePlanGroup('明天',tomorrow)}${carePlanGroup('本周',thisWeek)}${carePlanGroup('更晚',later)}${!plans.length?careEmpty('近期暂无计划','可添加护理、复诊或疫苗任务'):''}<button class="care-med-entry care-med-management" data-route="medication">${I('pill')}<div><b>用药管理</b><small>管理剂量、频次与提醒</small></div>${I('chevron')}</button>`;}
renderCareHub=function(){careHeader('照护');if(careTab==='已完成')careTab='今日';const c=careStore(),items=careOccurrences().sort((a,b)=>a.time.localeCompare(b.time)),pending=items.filter(t=>!t.done),done=items.filter(t=>t.done),next=pending[0];scroll.innerHTML=`<div class="care-hub-top"><div class="care-pet-line">${avatar()}<div><b>${esc(currentPet().name)}的照护</b><small>${careToday().replaceAll('-','.')} · ${pending.length?'还有 '+pending.length+' 项待完成':'今日照护已完成'}</small></div><button class="care-history-entry" data-care-history>完成记录 ${I('chevron')}</button></div><div class="care-glance"><div><span>今日完成</span><b>${done.length}/${items.length}</b></div><div class="care-glance-progress"><i style="width:${items.length?done.length/items.length*100:0}%"></i></div><p>下一任务 <b>${next?esc(next.time+' '+next.name):'暂无'}</b></p></div></div><div class="care-segments care-main-tabs" role="tablist" aria-label="照护分类">${['今日','计划'].map(t=>`<button role="tab" aria-selected="${careTab===t}" class="${careTab===t?'selected':''}" data-care-tab="${t}">${t}</button>`).join('')}</div>${careTab==='今日'?renderCareToday(items,done,pending):renderCarePlan(c)}`;};
window.addEventListener('click',e=>{const b=e.target.closest('[data-care-date]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();carePlanSelectedDate=b.dataset.careDate;render();},true);
render();

/* Care header refinement: reuse the Home pet card and keep history as a quiet action. */
function careHubPetCard(){const p=currentPet();return `<section class="pet care-hub-pet"><button type="button" class="care-pet-card-hit" data-route="petdetail" aria-label="查看${esc(p.name)}的宠物档案"><div class="pet-copy"><span class="pet-name">${esc(p.name)} ${I('chevron')}</span><p>${esc(p.breed)}　${petAge(p)}　${esc(p.sex)}</p><span class="health">${I('heart')}${p.id==='doudou'?'当前状态良好':'健康待记录'}</span><p class="quote">健康的每一天<br>都是一起更久的可能</p></div><div class="cat ${p.photo==='dog'?'dog-avatar':p.photo==='none'?'plain-avatar':''}" role="img" aria-label="${esc(p.name)}的照片"></div></button></section>`;}
renderCareHub=function(){careHeader('照护');header.querySelector('.page-head')?.classList.add('care-page-head');if(careTab==='已完成')careTab='今日';const c=careStore(),items=careOccurrences().sort((a,b)=>a.time.localeCompare(b.time)),pending=items.filter(t=>!t.done),done=items.filter(t=>t.done);scroll.innerHTML=`<div class="care-hub-top">${careHubPetCard()}<div class="care-pet-actions"><span>${careToday().replaceAll('-','.')} · ${pending.length?'还有 '+pending.length+' 项待完成':'今日照护已完成'}</span><button class="care-history-entry" data-care-history>完成记录 ${I('chevron')}</button></div></div><div class="care-segments care-main-tabs" role="tablist" aria-label="照护分类">${['今日','计划'].map(t=>`<button role="tab" aria-selected="${careTab===t}" class="${careTab===t?'selected':''}" data-care-tab="${t}">${t}</button>`).join('')}</div>${careTab==='今日'?renderCareToday(items,done,pending):renderCarePlan(c)}`;};
render();

/* Every pet identity card shares the same photo-led Home treatment. */
function sharedHomePetCard(p=currentPet(),options={}){const action=options.switcher?'data-symptom-pet-picker':options.edit?'data-pet-action="edit"':'data-route="petdetail"',status=options.status||'当前状态良好';return `<section class="pet shared-home-pet"><button type="button" class="shared-home-pet-hit" ${action} aria-label="${options.switcher?'切换':'查看'}${esc(p.name)}"><div class="pet-copy"><span class="pet-name">${esc(p.name)} ${I('chevron')}</span><p>${esc(p.breed)}　${petAge(p)}　${esc(p.sex)}</p><span class="health">${I(options.record?'record':'heart')}${esc(status)}</span><p class="quote">健康的每一天<br>都是一起更久的可能</p></div><div class="cat ${p.photo==='dog'?'dog-avatar':p.photo==='none'?'plain-avatar':''}" role="img" aria-label="${esc(p.name)}的照片"></div></button></section>`;}
function unifyPetIdentityCards(root=scroll){if(!root?.querySelectorAll)return;const p=currentPet(),status=state.route==='symptom'||state.route==='hospitals'?(state.symptoms.length?'症状待评估':'健康待记录'):state.route==='visit'?'就诊记录':state.route==='medication'?(state.medTab==='用药历史'?'历史照护记录':'今日用药照护'):state.route==='archive'?'医疗档案':'当前状态良好';root.querySelectorAll('.pet-mini,.archive-pet,.med-pet,.pet-detail-hero,.symptom-pet-card').forEach(card=>{if(card.classList.contains('shared-home-pet'))return;const holder=document.createElement('div');holder.innerHTML=sharedHomePetCard(p,{switcher:card.classList.contains('symptom-pet-card')&&(state.route==='symptom'||state.route==='hospitals'),edit:card.classList.contains('pet-detail-hero'),record:state.route==='visit',status});card.replaceWith(holder.firstElementChild);});}
const renderBeforeSharedPetCards=render;render=function(){renderBeforeSharedPetCards();unifyPetIdentityCards(scroll);};
new MutationObserver(()=>{if(sheet.open)unifyPetIdentityCards(sheet.querySelector('#sheet-body'));}).observe(sheet,{childList:true,subtree:true});
window.addEventListener('click',e=>{const b=e.target.closest('.shared-home-pet-hit[data-symptom-pet-picker]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();modal('选择本次就医的宠物',`<div class="symptom-pet-options">${petStore.pets.map(p=>`<button data-symptom-pet="${esc(p.id)}" aria-pressed="${p.id===currentPet().id}">${avatar(p)}<div><b>${esc(p.name)}</b><p>${esc(p.breed)} · ${petAge(p)}</p></div>${I(p.id===currentPet().id?'check':'chevron')}</button>`).join('')}</div>`);},true);
render();

/* Unified care-plan management: definitions live in Plan; occurrences live in Today. */
carePlanSelectedDate='';
const careOccurrencesBeforePlanPause=careOccurrences;
careOccurrences=function(){const c=careStore();return careOccurrencesBeforePlanPause().filter(item=>item.med?!item.med.paused:!c.tasks.find(t=>t.id===item.id)?.paused);};
function carePlanDefinitions(){const c=careStore(),today=careToday(),items=[];state.meds.filter(m=>!m.ended&&medEnd(m)>=today).forEach(m=>items.push({kind:'med',id:String(m.id),type:'用药',name:m.name,important:false,paused:!!m.paused,start:m.startDate,end:medEnd(m),source:m}));c.tasks.filter(t=>taskEnd(t)>=today&&(t.repeat||!c.history.some(h=>h.id===t.id))).forEach(t=>items.push({kind:'task',id:t.id,type:t.type,name:t.name,important:['复诊','疫苗'].includes(t.type),paused:!!t.paused,start:t.date,end:taskEnd(t),source:t}));return items.sort((a,b)=>Number(b.important)-Number(a.important)||a.start.localeCompare(b.start));}
function carePlanRunsOn(plan,date){return date>=plan.start&&date<=plan.end&&(plan.kind==='med'||plan.source.repeat||plan.start===date);}
function carePlanSchedule(plan){const x=plan.source;if(plan.kind==='med')return `每日 ${timesFor(x).length} 次｜连续 ${x.days} 天`;if(x.repeat)return `每日 1 次｜连续 ${x.days} 天`;return `${x.date.slice(5).replace('-','月')}日 ${x.time}`;}
function carePlanNext(plan){const x=plan.source;if(plan.paused)return '已暂停';if(plan.kind==='med'){const date=x.startDate>careToday()?x.startDate:careToday();return `${date===careToday()?'今天':date.slice(5).replace('-','/')} ${timesFor(x)[0]||'待设置'}`;}return `${x.date===careToday()?'今天':x.date.slice(5).replace('-','/')} ${x.time}`;}
function careDefinitionCard(plan){return `<button class="care-definition-card ${plan.important?'important':''}" data-care-plan-detail="${plan.kind}:${esc(plan.id)}"><span class="care-task-symbol">${I(careIcon(plan.type))}</span><div class="care-definition-copy"><div><small>${esc(plan.type)}</small><span class="care-plan-state ${plan.paused?'paused':''}">${plan.paused?'已暂停':'进行中'}</span></div><b>${esc(plan.name)}</b><p>${esc(carePlanSchedule(plan))}</p><em>下一次：${esc(carePlanNext(plan))}</em></div>${I('chevron')}</button>`;}
renderCarePlan=function(){const today=careToday(),week=Array.from({length:7},(_,i)=>careShift(today,i)),plans=carePlanDefinitions(),filtered=carePlanSelectedDate?plans.filter(p=>carePlanRunsOn(p,carePlanSelectedDate)):plans,weekEnd=careShift(today,7),reviews=plans.filter(p=>p.type==='复诊'&&p.start<=weekEnd).length;return `<div class="care-plan-toolbar"><div class="care-week-strip care-plan-filter"><button class="${!carePlanSelectedDate?'selected':''}" data-care-date=""><span>全部</span><b>${plans.length}</b><i></i></button>${week.map((date,i)=>`<button class="${carePlanSelectedDate===date?'selected':''}" data-care-date="${date}"><span>${i===0?'今天':'周'+careDayLabel(date)}</span><b>${+date.slice(-2)}</b><i></i></button>`).join('')}</div><section class="care-plan-summary unified"><div><span>照护计划</span><b>进行中 ${plans.filter(p=>!p.paused).length} 个计划</b></div><em>本周 ${reviews} 次复诊</em></section><button class="care-new-plan" data-care-new-plan>${I('plus')}新建照护计划</button></div><div class="care-plan-list-heading"><h2>${carePlanSelectedDate?`${carePlanSelectedDate===today?'今天':carePlanSelectedDate.slice(5).replace('-','月')+'日'}执行任务`:'全部照护计划'}</h2><span>${filtered.length} 个</span></div><div class="care-definition-list">${filtered.map(careDefinitionCard).join('')||careEmpty(carePlanSelectedDate?'这一天暂无执行任务':'还没有照护计划','新建用药、复诊、疫苗、驱虫或护理计划')}</div>`;};
const renderCareTodayBeforePlanEntry=renderCareToday;
renderCareToday=function(items,done,pending){return `<button class="care-manage-plan" data-care-tab="计划"><span>${I('calendar')}</span><div><b>管理照护计划</b><small>用药、复诊、疫苗、驱虫与护理安排</small></div>${I('chevron')}</button>${renderCareTodayBeforePlanEntry(items,done,pending)}`;};
function openCarePlanDetail(plan){const x=plan.source,rows=plan.kind==='med'?[['单次剂量',x.dose],['频次',`每日 ${timesFor(x).length} 次`],['疗程',`${x.days} 天（${x.startDate}—${medEnd(x)}）`],['提醒时间',timesFor(x).join('、')]]:plan.type==='复诊'?[['日期',`${x.date} ${x.time}`],['医院',x.hospital||currentPet().visitHospital||'待确认'],['提醒',x.remind?'已开启':'未开启']]:['疫苗','驱虫'].includes(plan.type)?[['日期',`${x.date} ${x.time}`],['类型',plan.type],['周期',x.repeat?`连续 ${x.days} 天`:'单次计划']]:[['频次',x.repeat?'每日一次':'单次'],['时间',x.time],['备注',x.notes||'暂无备注']];modal(`${plan.type}计划详情`,`<div class="care-plan-detail-head"><span class="care-task-symbol">${I(careIcon(plan.type))}</span><div><small>${esc(plan.type)}</small><h3>${esc(plan.name)}</h3><span class="care-plan-state ${plan.paused?'paused':''}">${plan.paused?'已暂停':'进行中'}</span></div></div><dl class="care-plan-detail-list">${rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'待设置')}</dd></div>`).join('')}</dl><details class="care-more-settings"><summary>更多设置 ${I('chevron')}</summary><p>开始日期：${esc(plan.start)}</p><p>提醒与执行记录会保留在当前宠物档案中。</p></details><div class="care-plan-detail-actions"><button data-care-plan-edit="${plan.kind}:${esc(plan.id)}">编辑</button><button data-care-plan-pause="${plan.kind}:${esc(plan.id)}">${plan.paused?'恢复':'暂停'}</button><button class="danger" data-care-plan-delete="${plan.kind}:${esc(plan.id)}">删除</button></div>`);}
function findCareDefinition(key){const [kind,...parts]=key.split(':');const id=parts.join(':');return carePlanDefinitions().find(p=>p.kind===kind&&String(p.id)===id);}
window.addEventListener('click',e=>{const b=e.target.closest('[data-care-new-plan],[data-new-plan-type],[data-care-plan-detail],[data-care-plan-edit],[data-care-plan-pause],[data-care-plan-delete]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.hasAttribute('data-care-new-plan')){modal('新建照护计划',`<div class="care-new-types">${[['用药','pill'],['复诊','calendar'],['疫苗','shield'],['驱虫','shield'],['护理','heart']].map(([type,icon])=>`<button data-new-plan-type="${type}"><span>${I(icon)}</span><b>${type}</b>${I('chevron')}</button>`).join('')}</div>`);return;}if(b.dataset.newPlanType){const type=b.dataset.newPlanType;sheet.close();if(type==='用药')addMed();else editCareTask('',type);return;}const key=b.dataset.carePlanDetail||b.dataset.carePlanEdit||b.dataset.carePlanPause||b.dataset.carePlanDelete,plan=findCareDefinition(key);if(!plan)return;if(b.dataset.carePlanDetail){openCarePlanDetail(plan);return;}if(b.dataset.carePlanEdit){sheet.close();plan.kind==='med'?medicationSettings(+plan.id):editCareTask(plan.id);return;}if(b.dataset.carePlanPause){plan.source.paused=!plan.source.paused;savePets();sheet.close();render();toast(plan.source.paused?'计划已暂停':'计划已恢复');return;}if(b.dataset.carePlanDelete){openLightEditor('删除照护计划',`<form id="care-plan-delete-confirm"><p>删除后不再生成今日任务，已有完成记录仍会保留。</p></form>`,()=>{if(plan.kind==='med')state.meds=state.meds.filter(m=>String(m.id)!==String(plan.id));else{const c=careStore();c.tasks=c.tasks.filter(t=>t.id!==plan.id);}savePets();closeLightEditor();if(sheet.open)sheet.close();render();toast('照护计划已删除');});}},true);
render();
const renderBeforeFinalClassicVisit=render;render=function(){renderBeforeFinalClassicVisit();restoreClassicVisitDetail();};
render();

/* Medical archive cards share the compact hierarchy of Home health overview. */
function refineArchiveOverviewCards(){scroll.classList.toggle('archive-overview-page',state.route==='archive');if(state.route!=='archive')return;scroll.querySelectorAll('.timeline-item').forEach(item=>{const article=item.querySelector('article');if(!article||article.querySelector('.archive-card-kicker'))return;const type=item.querySelector('.timeline-date span')?.textContent||'健康记录';article.insertAdjacentHTML('afterbegin',`<div class="archive-card-kicker"><span>${esc(type)}</span><em>已归档</em></div>`);});scroll.querySelectorAll(':scope>.section-block').forEach(card=>{if(card.classList.contains('archive-overview-card'))return;card.classList.add('archive-overview-card');const label=state.archiveTab==='检查报告'?'检查资料':state.archiveTab==='诊断记录'?'诊疗记录':state.archiveTab==='疫苗驱虫'?'预防照护':'健康记录';card.insertAdjacentHTML('afterbegin',`<div class="archive-card-kicker"><span>${label}</span><em>${state.archiveTab==='疫苗驱虫'?'计划记录':'已归档'}</em></div>`);});}
const renderBeforeArchiveOverviewCards=render;render=function(){renderBeforeArchiveOverviewCards();refineArchiveOverviewCards();};
render();

/* Profile is an account and pet-management center, not a duplicate business hub. */
function refineProfileCenter(){if(state.route!=='profile')return;const links=scroll.querySelector('.profile-links');if(!links)return;links.outerHTML=`<section class="profile-center"><h2>个人中心</h2><div class="profile-center-list"><button data-account="edit">${I('user')}<div><b>主人资料</b><small>昵称、联系方式与所在城市</small></div>${I('chevron')}</button><button data-profile-center="notifications">${I('bell')}<div><b>提醒与通知</b><small>照护提醒与通知偏好</small></div>${I('chevron')}</button><button data-profile-center="family">${I('heart')}<div><b>家庭成员与共同照护</b><small>邀请家人一起照顾宠物</small></div>${I('chevron')}</button><button data-account="privacy">${I('shield')}<div><b>隐私与账号</b><small>本地数据、账号与隐私说明</small></div>${I('chevron')}</button><button data-profile-center="help">${I('record')}<div><b>帮助反馈</b><small>常见问题与意见反馈</small></div>${I('chevron')}</button><button data-account="about">${I('paw')}<div><b>关于 PawCare</b><small>版本信息与产品介绍</small></div>${I('chevron')}</button></div></section>`;const heading=scroll.querySelector('.pet-selector .section-heading');if(heading&&!heading.querySelector('[data-profile-manage-pets]')){const add=heading.querySelector('[data-pet-action="add"]');add?.insertAdjacentHTML('beforebegin',`<button class="profile-manage-pets" data-profile-manage-pets>管理宠物</button>`);}const hint=scroll.querySelector('.microcopy.centered');if(hint)hint.innerHTML='“我的”仅管理主人、宠物和账号设置。<br>医疗资料请前往档案，照护安排请前往照护。';}
const renderBeforeProfileCenter=render;render=function(){renderBeforeProfileCenter();refineProfileCenter();};
window.addEventListener('click',e=>{const b=e.target.closest('[data-profile-center],[data-profile-manage-pets]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.hasAttribute('data-profile-manage-pets')){modal('管理宠物',`<div class="profile-pet-management">${petStore.pets.map(p=>`<button data-pet-edit="${esc(p.id)}">${avatar(p)}<div><b>${esc(p.name)}</b><small>${esc(p.breed)} · ${petAge(p)}</small></div>${I('chevron')}</button>`).join('')}</div><button class="add-button" data-pet-action="add">${I('plus')}添加宠物</button>`);return;}if(b.dataset.profileCenter==='notifications'){accountSettings();return;}if(b.dataset.profileCenter==='family'){modal('家庭成员与共同照护',`<div class="detail"><b>共同照护正在规划中</b><p>后续可邀请家庭成员，共享照护计划、提醒与完成状态。</p></div><button class="outline-btn" data-profile-invite>邀请家庭成员</button>`);return;}if(b.dataset.profileCenter==='help'){modal('帮助反馈',`<div class="account-menu"><button data-help-topic="使用帮助">${I('record')}<div><b>使用帮助</b><small>了解档案、就医与照护功能</small></div>${I('chevron')}</button><button data-help-topic="意见反馈">${I('edit')}<div><b>意见反馈</b><small>告诉我们你的建议</small></div>${I('chevron')}</button></div>`);}},true);
render();

/* Rich type picker for creating a care plan. */
function prepareCarePlanTypePicker(){if(state.route!=='carehub')return;scroll.querySelector('[data-care-new-plan]')?.setAttribute('data-care-new-plan-v2','');scroll.querySelector('[data-care-new-plan-v2]')?.removeAttribute('data-care-new-plan');}
const renderBeforeCarePlanTypePicker=render;render=function(){renderBeforeCarePlanTypePicker();prepareCarePlanTypePicker();};
window.addEventListener('click',e=>{const b=e.target.closest('[data-care-new-plan-v2]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const types=[['用药','pill','设置剂量、频次与疗程'],['复诊','calendar','安排复诊日期和提醒'],['疫苗','shield','记录接种类型与周期'],['驱虫','shield','规划体内外驱虫时间']];modal('新建照护计划',`<div class="care-type-picker"><p class="care-type-intro">选择要创建的照护类型</p><div class="care-type-grid">${types.map(([type,icon,desc])=>`<button data-new-plan-type="${type}"><span>${I(icon)}</span><div><b>${type}</b><small>${desc}</small></div>${I('chevron')}</button>`).join('')}</div><button class="care-type-nursing" data-new-plan-type="护理"><span>${I('heart')}</span><div><b>护理</b><small>创建清洁、伤口或日常护理安排</small></div>${I('chevron')}</button></div>`);},true);
render();

/* Selecting a type transitions inside the current sheet instead of exposing Care behind it. */
function upgradeCareTypeButtons(){sheet.querySelectorAll('.care-type-picker [data-new-plan-type]').forEach(b=>{b.dataset.newPlanTypeV2=b.dataset.newPlanType;b.removeAttribute('data-new-plan-type');});}
new MutationObserver(upgradeCareTypeButtons).observe(sheet,{childList:true,subtree:true});
function openNewCareTaskInSheet(type){const defaultName=type==='复诊'?'复诊':type==='疫苗'?'疫苗接种':type==='驱虫'?'定期驱虫':'日常护理';modal(`新建${type}计划`,`<form id="care-task-create-v2" class="entry-form"><input type="hidden" name="type" value="${type}"><label>计划名称<input name="name" maxlength="40" value="${defaultName}" required></label><div class="form-row"><label>开始日期<input name="date" type="date" value="${careToday()}" required></label><label>执行时间<input name="time" type="time" value="09:00" required></label></div><label>执行方式<select name="repeat"><option value="once">仅一次</option><option value="daily">每日一次</option></select></label><label data-create-days hidden>持续天数<input name="days" type="number" min="1" max="365" value="7"></label><label>备注<textarea name="notes" maxlength="300" placeholder="补充照护要求或注意事项"></textarea></label><label class="plan-reminder"><input type="checkbox" name="remind" checked>开启提醒</label><button type="submit" class="cta">创建${type}计划</button></form>`);const form=sheet.querySelector('#care-task-create-v2');form.querySelector('[name=repeat]').onchange=e=>form.querySelector('[data-create-days]').hidden=e.target.value!=='daily';}
window.addEventListener('click',e=>{const b=e.target.closest('[data-new-plan-type-v2]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const type=b.dataset.newPlanTypeV2;if(type==='用药')addMed();else openNewCareTaskInSheet(type);},true);
window.addEventListener('submit',e=>{if(e.target.id!=='care-task-create-v2')return;e.preventDefault();e.stopImmediatePropagation();const d=Object.fromEntries(new FormData(e.target)),repeat=d.repeat==='daily';careStore().tasks.push({id:careId(),type:d.type,name:d.name.trim(),date:d.date,time:d.time,repeat,days:repeat?+d.days:1,remind:new FormData(e.target).has('remind'),notes:d.notes.trim()});savePets();sheet.close();carePlanSelectedDate='';render();toast(`${d.type}计划已创建`);},true);
render();

/* Lightweight, non-interactive account identity at the top of Profile. */
function refineProfileIdentity(){if(state.route!=='profile')return;const owner=scroll.querySelector('.owner-card');if(!owner)return;const a=accountData();owner.outerHTML=`<section class="profile-user-summary" aria-label="当前用户信息"><span class="profile-user-avatar">${I('user')}</span><div><b>${esc(a.name||'宠物照护者')}</b><small>已绑定 ${petStore.pets.length} 只宠物</small></div></section>`;}
const renderBeforeProfileIdentity=render;render=function(){renderBeforeProfileIdentity();refineProfileIdentity();};
render();
